    $describe = function (array $fields) {
        $scope = ['auth' => ['label' => 'نوع منبع داده', 'options' => LaunchpadForm::authChoices()]] + $fields;
        $condition = fn (?string $when) => $when === null ? '' : '؛ فقط وقتی ' . collect(explode(',', $when))->map(function ($term) use ($scope) {
            [$key, $value] = preg_split('/!?=/', $term);
            $label = collect(explode('|', $value))->map(fn ($item) => ($scope[$key]['options'][$item] ?? $item))->map(fn ($label) => strstr($label, ' (', true) ?: $label)->implode('» یا «');

            return '«' . $scope[$key]['label'] . '» روی «' . $label . (str_contains($term, '!=') ? '» نباشد' : '» باشد');
        })->implode(' و ');

        return collect($fields)->map(fn ($spec) => $spec['label'] . ' (' . ($spec['required'] ? 'لازم است' : 'اختیاری است') . $condition($spec['when'] ?? null) . '): ' . ($spec['hint'] ?? implode(' / ', $spec['options'] ?? [])) . ($spec['placeholder'] ? ' نمونه: ' . $spec['placeholder'] : ''))->implode(' ');
    };

